import React, { useMemo, useState } from 'react';
import {
  Activity, Award, BadgeCheck, CalendarDays, ChevronLeft, ChevronRight, CircleAlert, Clock3, FileCheck2,
  Fingerprint, Gavel, LayoutDashboard, ListChecks, LockKeyhole, Network, Plus, QrCode, RadioTower,
  Search, Settings2, ShieldCheck, Sparkles, Trash2, UsersRound, WandSparkles
} from 'lucide-react';
import { useAppStore } from '../../lib/store';
import { COMPETITION_TEMPLATES, getCompetitionPolicy } from '../../lib/competition-config';
import { Category, Competition, CompetitionPolicy, RegistrationFieldDefinition } from '../../types';
import { Button } from '../design-system/Button';
import { Badge } from '../design-system/Badge';
import { EnterpriseWorkspace } from './EnterpriseWorkspace';

const isAr=(language:string)=>language==='ar';
type MainView='overview'|'design'|'participants'|'operations'|'results'|'enterprise';
type PolicySection='identity'|'registration'|'workflow'|'operations'|'questions'|'judging'|'appeals'|'results'|'certificate'|'privacy';

type Store=ReturnType<typeof useAppStore>;

export const CompetitionOverview: React.FC = () => {
 const store=useAppStore(); const {competition,participants,committees,reviewCases,results,certificates,auditLogs,appeals,language}=store; const ar=isAr(language);
 const policy=getCompetitionPolicy(competition); const readiness=store.getCompetitionReadiness();
 const [view,setView]=useState<MainView>('overview'); const [section,setSection]=useState<PolicySection>('identity'); const [query,setQuery]=useState(''); const [simCount,setSimCount]=useState(Math.max(1,committees.length));
 const sim=useMemo(()=>store.runSimulation(simCount,30),[simCount,participants.length,committees.length,competition.ruleSet.questionDurationMinutes]);
 const filtered=participants.filter(p=>`${p.code} ${p.fullName} ${p.fullNameArabic} ${p.country}`.toLowerCase().includes(query.toLowerCase()));
 const attention=[...readiness.map(i=>({id:i.id,title:ar?i.ar:i.en,kind:'setup'})),...reviewCases.filter(r=>r.status==='pending').slice(0,3).map(r=>({id:r.id,title:ar?`مراجعة ${r.participantCode}`:`Review ${r.participantCode}`,kind:'review'})),...store.incidents.filter(i=>i.status!=='resolved').slice(0,2).map(i=>({id:i.id,title:i.title,kind:'incident'}))];
 const patchPolicy=(mutate:(p:CompetitionPolicy)=>void)=>store.updateCompetitionPolicy(p=>{mutate(p);return p});
 const nav=[{id:'overview' as const,icon:LayoutDashboard,ar:'اليوم',en:'Overview'},{id:'design' as const,icon:Settings2,ar:'DNA المسابقة',en:'Competition DNA'},{id:'participants' as const,icon:UsersRound,ar:'المشاركون',en:'Participants'},{id:'operations' as const,icon:RadioTower,ar:'التشغيل',en:'Operations'},{id:'results' as const,icon:Award,ar:'النتائج',en:'Results'},{id:'enterprise' as const,icon:ShieldCheck,ar:'المؤسسة',en:'Enterprise'}];
 return <div className="max-w-[1500px] mx-auto px-4 sm:px-6 py-5 sm:py-7"><div className="flex gap-6">
  <aside className="hidden lg:block w-52 shrink-0 pt-1"><div className="sticky top-24 space-y-1"><div className="px-3 mb-4"><div className="text-[10px] font-black tracking-[.16em] text-[#7c827e]">{competition.edition}</div><div className="mt-1 text-sm font-extrabold text-[#303733] line-clamp-2">{ar?competition.nameArabic:competition.name}</div></div>{nav.map(n=><NavButton key={n.id} active={view===n.id} onClick={()=>setView(n.id)} icon={n.icon} label={ar?n.ar:n.en}/>)}</div></aside>
  <main className="min-w-0 flex-1">
   <div className="lg:hidden flex gap-1 overflow-x-auto pb-4 mb-4 border-b border-[#dfded7]">{nav.map(n=><button key={n.id} onClick={()=>setView(n.id)} className={`shrink-0 flex items-center gap-2 px-3 py-2 rounded-xl text-xs font-bold ${view===n.id?'bg-[#214C40] text-white':'bg-white border border-[#dfded7] text-[#626a65]'}`}><n.icon className="w-4 h-4"/>{ar?n.ar:n.en}</button>)}</div>
   {view==='overview'&&<Overview store={store} ar={ar} attention={attention} readiness={readiness} onConfigure={()=>setView('design')}/>} 
   {view==='design'&&<CompetitionDNA store={store} ar={ar} policy={policy} section={section} setSection={setSection} patchPolicy={patchPolicy}/>} 
   {view==='participants'&&<ParticipantsView store={store} ar={ar} query={query} setQuery={setQuery} filtered={filtered}/>} 
   {view==='operations'&&<OperationsView store={store} ar={ar} sim={sim} simCount={simCount} setSimCount={setSimCount} attention={attention}/>} 
   {view==='results'&&<ResultsView store={store} ar={ar}/>} 
   {view==='enterprise'&&<EnterpriseWorkspace/>} 
  </main>
 </div></div>;
};

const Overview=({store,ar,attention,readiness,onConfigure}:{store:Store;ar:boolean;attention:any[];readiness:any[];onConfigure:()=>void})=>{
 const {competition,participants,committees,sealApprovals}=store; const canPublish=['draft','configured'].includes(competition.status);
 const publish=()=>store.publishCompetition();
 return <div className="space-y-5">
  <section className="mizan-surface p-6 sm:p-8"><div className="flex flex-col md:flex-row md:items-end justify-between gap-5"><div><div className="flex flex-wrap items-center gap-2"><Badge>{competition.status}</Badge><Badge variant="neutral" dot={false}>{competition.automationLevel}</Badge></div><h1 className="mizan-title text-3xl sm:text-4xl font-black mt-3">{ar?competition.nameArabic:competition.name}</h1><p className="mizan-muted text-sm mt-2">{competition.venueName||'—'} · {competition.startDate||'—'}</p></div><div className="flex gap-2"><Button onClick={onConfigure} variant="outline" icon={<Settings2 className="w-4 h-4"/>}>{ar?'ضبط':'Configure'}</Button>{canPublish&&<Button disabled={readiness.length>0} onClick={publish} icon={<Activity className="w-4 h-4"/>}>{ar?'فتح التسجيل':'Open registration'}</Button>}</div></div></section>
  <section className="grid grid-cols-3 gap-3"><MetricCard icon={UsersRound} value={participants.length} label={ar?'مشارك':'Participants'}/><MetricCard icon={Clock3} value={participants.filter(p=>p.status==='in_queue').length} label={ar?'ينتظر':'Waiting'}/><MetricCard icon={Gavel} value={committees.filter(c=>c.status!=='offline').length} label={ar?'لجان نشطة':'Active panels'}/></section>
  <section className="grid xl:grid-cols-[1.35fr_.65fr] gap-4">
   <div className="mizan-surface p-5 sm:p-6"><div className="flex items-center justify-between gap-3"><div><div className="mizan-kicker">LIVE FLOW</div><h2 className="font-extrabold mt-1">{ar?'من التسجيل إلى الشهادة':'Registration to certificate'}</h2></div><Badge variant={readiness.length?'amber':'emerald'}>{readiness.length?`${readiness.length} ${ar?'ملاحظات':'items'}`:(ar?'جاهز':'Ready')}</Badge></div><div className="flex gap-1.5 overflow-x-auto mt-5">{getCompetitionPolicy(store.competition).workflow.filter(w=>w.enabled).map((w,i,all)=><React.Fragment key={w.id}><div title={workflowLabel(w.id,ar)} className={`shrink-0 w-9 h-9 rounded-xl grid place-items-center text-xs font-black ${w.automated?'bg-[#E7EEE9] text-[#214C40]':'bg-[#F2EADC] text-[#7d5e34]'}`}>{i+1}</div>{i<all.length-1&&<div className="shrink-0 w-4 h-px bg-[#d9d7d0] self-center"/>}</React.Fragment>)}</div><div className="mt-4 text-xs text-[#727974]">{ar?'الأخضر مؤتمت · الذهبي قرار بشري':'Green automated · gold human decision'}</div>{getCompetitionPolicy(store.competition).results.requireDualApprovalToSeal&&sealApprovals.length>0&&<div className="text-[11px] text-[#7d5e34] mt-3">{ar?`اعتمادات الختم الحالية: ${new Set(sealApprovals.map(a=>a.actorId)).size}/2`:`Seal approvals: ${new Set(sealApprovals.map(a=>a.actorId)).size}/2`}</div>}</div>
   <div className="mizan-surface p-5 sm:p-6"><div className="flex items-center justify-between"><div><div className="mizan-kicker">NEEDS ATTENTION</div><h2 className="font-extrabold mt-1">{attention.length}</h2></div><CircleAlert className={`w-5 h-5 ${attention.length?'text-[#9B7542]':'text-[#2F6555]'}`}/></div><div className="mt-4">{attention.length?attention.slice(0,5).map(x=><div key={x.id} className="py-2.5 border-b border-[#ebe9e3] last:border-0 text-xs font-semibold text-[#454c48]">{x.title}</div>):<div className="py-6 text-center"><BadgeCheck className="w-6 h-6 text-[#2F6555] mx-auto"/><div className="text-xs font-bold mt-2">{ar?'لا شيء يحتاج تدخلك':'Nothing needs intervention'}</div></div>}</div></div>
  </section>
 </div>;
};

const CompetitionDNA=({store,ar,policy,section,setSection,patchPolicy}:{store:Store;ar:boolean;policy:CompetitionPolicy;section:PolicySection;setSection:(s:PolicySection)=>void;patchPolicy:(fn:(p:CompetitionPolicy)=>void)=>void})=>{
 const {competition}=store; const sections:[PolicySection,React.ComponentType<{className?:string}>,string][]=[['identity',Fingerprint,ar?'الهوية والفئات':'Identity & categories'],['registration',FileCheck2,ar?'التسجيل والشروط':'Registration'],['workflow',Network,ar?'المسار':'Workflow'],['operations',QrCode,ar?'التشغيل':'Operations'],['questions',Sparkles,ar?'الأسئلة':'Questions'],['judging',Gavel,ar?'التحكيم':'Judging'],['appeals',ListChecks,ar?'الاعتراضات':'Appeals'],['results',LockKeyhole,ar?'النتائج':'Results'],['certificate',Award,ar?'الشهادة':'Certificates'],['privacy',ShieldCheck,ar?'الخصوصية':'Privacy']];
 return <div className="space-y-4">
  <div><div className="mizan-kicker">MIZAN COMPETITION DNA</div><h1 className="text-2xl sm:text-3xl font-black mt-1">{ar?'كل مسابقة لها نظامها':'Every competition is its own system'}</h1><p className="text-sm text-[#727974] mt-2 max-w-2xl">{ar?'لا توجد لائحة عالمية مفروضة. كل شرط وكل زر تحكيم وكل مرحلة تخص هذه المسابقة وحدها.':'No global rules are imposed. Registration, judging actions, workflow and policies belong to this competition only.'}</p></div>
  <div className="mizan-surface p-4"><div className="flex items-center gap-3 overflow-x-auto"><WandSparkles className="w-4 h-4 text-[#2F6555] shrink-0"/><span className="text-xs font-bold shrink-0">{ar?'قالب بداية':'Starting template'}</span>{COMPETITION_TEMPLATES.map(t=><button key={t.id} onClick={()=>store.applyTemplate(t.id)} className={`shrink-0 rounded-xl px-3 py-2 text-xs font-bold border ${policy.templateId===t.id?'bg-[#214C40] text-white border-[#214C40]':'bg-white text-[#4a514d] border-[#dedcd4] hover:bg-[#f4f2ec]'}`}>{ar?t.nameArabic:t.nameEnglish}</button>)}</div></div>
  <div className="grid lg:grid-cols-[220px_1fr] gap-4">
   <div className="mizan-surface p-2 h-fit"><div className="grid grid-cols-2 lg:grid-cols-1 gap-1">{sections.map(([id,Icon,label])=><button key={id} onClick={()=>setSection(id)} className={`flex items-center gap-2 px-3 py-2.5 rounded-xl text-xs sm:text-sm font-bold text-start ${section===id?'bg-[#E7EEE9] text-[#214C40]':'text-[#626a65] hover:bg-[#f2f0ea]'}`}><Icon className="w-4 h-4 shrink-0"/><span className="truncate">{label}</span></button>)}</div></div>
   <div className="mizan-surface p-5 sm:p-7 min-h-[520px]">
    {section==='identity'&&<IdentitySection store={store} ar={ar}/>} 
    {section==='registration'&&<RegistrationSection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='workflow'&&<WorkflowSection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='operations'&&<OperationsPolicySection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='questions'&&<QuestionsSection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='judging'&&<JudgingSection store={store} ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='appeals'&&<AppealsSection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='results'&&<ResultPolicySection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='certificate'&&<CertificateSection ar={ar} policy={policy} patch={patchPolicy}/>} 
    {section==='privacy'&&<PrivacySection ar={ar} policy={policy} patch={patchPolicy}/>} 
   </div>
  </div>
 </div>;
};

const IdentitySection=({store,ar}:{store:Store;ar:boolean})=>{const c=store.competition; const [selected,setSelected]=useState(c.categories[0]?.id||''); const cat=c.categories.find(x=>x.id===selected);
 const patch=(p:Partial<Competition>)=>store.updateCompetitionDetails(p); const patchCat=(p:Partial<Category>)=>cat&&store.updateCategory(cat.id,p);
 return <div className="space-y-6"><SectionTitle title={ar?'هوية وفئات المسابقة':'Competition identity & categories'} subtitle={ar?'حتى الفئات يمكن أن ترتبط بلوائح وأسئلة مختلفة داخل المسابقة.':'Categories can point to different rule sets and question blueprints.'}/>
  <div className="grid sm:grid-cols-2 gap-4"><TextControl label={ar?'الاسم بالعربية':'Arabic name'} value={c.nameArabic} onChange={v=>patch({nameArabic:v})}/><TextControl label={ar?'الاسم بالإنجليزية':'English name'} value={c.name} onChange={v=>patch({name:v})}/><TextControl label={ar?'المنطقة الزمنية':'Timezone'} value={c.timezone} onChange={v=>patch({timezone:v})}/><TextControl label={ar?'المكان':'Venue'} value={c.venueName} onChange={v=>patch({venueName:v})}/><TextControl type="date" label={ar?'بداية المسابقة':'Start date'} value={c.startDate} onChange={v=>patch({startDate:v})}/><TextControl type="date" label={ar?'نهاية المسابقة':'End date'} value={c.endDate} onChange={v=>patch({endDate:v})}/><Control label={ar?'الأتمتة':'Automation'}><TinySelect value={c.automationLevel} onChange={v=>patch({automationLevel:v as any})}><option value="assisted">Assisted</option><option value="automated">Automated</option><option value="autopilot">Autopilot</option></TinySelect></Control></div>
  <div><div className="flex items-center justify-between"><div className="text-xs font-black text-[#6d746f]">{ar?'الفئات':'Categories'}</div><button onClick={()=>{const x=store.addCategory();setSelected(x.id)}} className="flex items-center gap-1 text-xs font-bold text-[#214C40]"><Plus className="w-3.5 h-3.5"/>{ar?'فئة':'Category'}</button></div><div className="flex gap-2 overflow-x-auto mt-3">{c.categories.map(x=><button key={x.id} onClick={()=>setSelected(x.id)} className={`shrink-0 rounded-xl px-3 py-2 text-xs font-bold border ${selected===x.id?'bg-[#E7EEE9] text-[#214C40] border-[#b7ccc2]':'border-[#deddd6] bg-white text-[#626a65]'}`}>{ar?x.nameArabic:x.name}</button>)}</div></div>
  {cat&&<div className="rounded-2xl bg-[#f4f2ec] p-4 sm:p-5 space-y-4"><div className="grid sm:grid-cols-2 gap-3"><TextControl label={ar?'اسم الفئة عربي':'Arabic category'} value={cat.nameArabic} onChange={v=>patchCat({nameArabic:v})}/><TextControl label={ar?'اسم الفئة إنجليزي':'English category'} value={cat.name} onChange={v=>patchCat({name:v})}/><TextControl label={ar?'الرواية / القراءة':'Riwaya / Qira’a'} value={cat.riwaya} onChange={v=>patchCat({riwaya:v})}/><TextControl label={ar?'نطاق الحفظ':'Scope'} value={cat.memorizationScope} onChange={v=>patchCat({memorizationScope:v})}/><NumberControl label={ar?'الأجزاء':'Juz'} value={cat.juzCount} onChange={v=>patchCat({juzCount:v})}/><NumberControl label={ar?'زمن مستهدف بالدقائق':'Target minutes'} value={cat.targetDurationMinutes} onChange={v=>patchCat({targetDurationMinutes:v})}/><NumberControl label={ar?'العمر الأدنى':'Minimum age'} value={cat.minAge||0} onChange={v=>patchCat({minAge:v||undefined})}/><NumberControl label={ar?'العمر الأعلى':'Maximum age'} value={cat.maxAge||0} onChange={v=>patchCat({maxAge:v||undefined})}/><Control label={ar?'الجنس حسب اللائحة':'Gender constraint'}><TinySelect value={cat.genderConstraint||'all'} onChange={v=>patchCat({genderConstraint:v as any})}><option value="all">{ar?'الكل':'All'}</option><option value="male">{ar?'رجال':'Male'}</option><option value="female">{ar?'نساء':'Female'}</option></TinySelect></Control><Control label={ar?'لائحة التحكيم':'Rule set'}><TinySelect value={cat.ruleSetId||c.ruleSet.id} onChange={v=>patchCat({ruleSetId:v})}>{(c.ruleSets||[c.ruleSet]).map(r=><option key={r.id} value={r.id}>{r.name} · {r.version}</option>)}</TinySelect></Control></div><div className="flex justify-end"><Button size="sm" variant="ghost" disabled={store.participants.some(p=>p.categoryId===cat.id)} onClick={()=>{if(store.removeCategory(cat.id))setSelected(c.categories.find(x=>x.id!==cat.id)?.id||'')}} icon={<Trash2 className="w-4 h-4"/>}>{ar?'حذف الفئة':'Remove category'}</Button></div></div>}
 </div>;
};

const RegistrationSection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'التسجيل والشروط':'Registration & eligibility'} subtitle={ar?'المتسابق يرى فقط الحقول التي تحتاجها هذه المسابقة.':'Participants see only the fields enabled for this competition.'}/><div className="grid sm:grid-cols-2 gap-4"><Control label={ar?'نوع التسجيل':'Registration mode'}><TinySelect value={policy.registration.mode} onChange={v=>patch(p=>{p.registration.mode=v as any})}><option value="public">{ar?'عام':'Public'}</option><option value="invitation">{ar?'دعوة':'Invitation'}</option><option value="delegation">{ar?'وفود':'Delegation'}</option><option value="hybrid">{ar?'هجين':'Hybrid'}</option></TinySelect></Control><Control label={ar?'طريقة الدخول':'Access'}><TinySelect value={policy.registration.accountMode} onChange={v=>patch(p=>{p.registration.accountMode=v as any})}><option value="otp">OTP</option><option value="magic_link">Magic link</option><option value="password">Password</option><option value="no_account">{ar?'بدون حساب':'No account'}</option></TinySelect></Control></div><div className="mizan-surface-soft px-4"><Toggle value={policy.registration.autoApproveEligible} onChange={v=>patch(p=>{p.registration.autoApproveEligible=v})} label={ar?'اعتماد تلقائي للحالات الموضوعية':'Auto-approve objective eligibility'}/><Toggle value={policy.registration.requireIdentityVerification} onChange={v=>patch(p=>{p.registration.requireIdentityVerification=v})} label={ar?'تحقق هوية':'Identity verification'}/><Toggle value={policy.registration.requireGuardianForMinors} onChange={v=>patch(p=>{p.registration.requireGuardianForMinors=v})} label={ar?'ولي أمر للقاصر':'Guardian for minors'}/></div><div><div className="text-xs font-black text-[#6d746f] mb-2">{ar?'حقول التسجيل':'Registration fields'}</div><div className="divide-y divide-[#e5e3dc] border-y border-[#e5e3dc]">{policy.registration.fields.map((f,i)=><RegistrationFieldRow key={f.id} f={f} ar={ar} onVisible={v=>patch(p=>{p.registration.fields[i].visible=v})} onRequired={v=>patch(p=>{p.registration.fields[i].required=v})}/>)}</div></div><div className="rounded-xl bg-[#F2EADC] text-[#725630] p-3 text-xs">{ar?'شروط الفئات (العمر/الجنس/النطاق) تطبق فوق هذه السياسة، وأي حالة غير محسومة تذهب للمراجعة البشرية.':'Category constraints (age/gender/scope) apply on top of this policy; unresolved cases go to human review.'}</div></div>;

const WorkflowSection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'المسار والأتمتة':'Workflow & automation'} subtitle={ar?'كل مرحلة يمكن تشغيلها أو أتمتتها أو اشتراط اعتماد بشري.':'Each stage can be enabled, automated, or approval-gated.'}/><div className="divide-y divide-[#e6e4dd]">{policy.workflow.map((w,i)=><div key={w.id} className="py-3 grid grid-cols-[36px_1fr_auto] items-center gap-3"><span className="w-8 h-8 rounded-xl bg-[#f0eee8] grid place-items-center text-xs font-black">{i+1}</span><div><div className="text-sm font-bold">{workflowLabel(w.id,ar)}</div><div className="text-[11px] text-[#7c837e]">{!w.enabled?(ar?'متوقف':'Disabled'):w.automated?(ar?'آلي':'Automated'):(ar?'بشري':'Human')}</div></div><div className="flex gap-1"><Chip active={w.enabled} onClick={()=>patch(p=>{p.workflow[i].enabled=!p.workflow[i].enabled})}>{w.enabled?(ar?'مفعّل':'On'):(ar?'متوقف':'Off')}</Chip>{w.enabled&&<Chip active={w.automated} amber={!w.automated} onClick={()=>patch(p=>{p.workflow[i].automated=!p.workflow[i].automated})}>{w.automated?(ar?'آلي':'Auto'):(ar?'بشري':'Human')}</Chip>}{w.enabled&&<Chip active={w.requiresApproval} amber onClick={()=>patch(p=>{p.workflow[i].requiresApproval=!p.workflow[i].requiresApproval})}>{ar?'اعتماد':'Approval'}</Chip>}</div></div>)}</div></div>;

const OperationsPolicySection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'سياسة التشغيل':'Operations policy'} subtitle={ar?'حدد إلى أي مدى تعمل المسابقة بلا موظفي استقبال أو توزيع يدوي.':'Choose how far the competition can run without reception or manual routing.'}/><div className="mizan-surface-soft px-4"><Toggle value={policy.operations.selfCheckIn} onChange={v=>patch(p=>{p.operations.selfCheckIn=v})} label={ar?'حضور ذاتي من الهاتف':'Mobile self check-in'}/><Toggle value={policy.operations.kioskCheckIn} onChange={v=>patch(p=>{p.operations.kioskCheckIn=v})} label={ar?'Kiosk ذاتي':'Self-service kiosk'}/><Toggle value={policy.operations.exceptionDesk} onChange={v=>patch(p=>{p.operations.exceptionDesk=v})} label={ar?'مكتب استثناء للحالات النادرة':'Exception desk'}/><Toggle value={policy.operations.smartArrivalSlots} onChange={v=>patch(p=>{p.operations.smartArrivalSlots=v})} label={ar?'مواعيد حضور ذكية':'Smart arrival slots'}/><Toggle value={policy.operations.autoRouting} onChange={v=>patch(p=>{p.operations.autoRouting=v})} label={ar?'توزيع تلقائي على اللجان':'Automatic committee routing'}/><Toggle value={policy.operations.publicQueueUsesCodesOnly} onChange={v=>patch(p=>{p.operations.publicQueueUsesCodesOnly=v})} label={ar?'الشاشات العامة تستخدم الأكواد':'Public queue uses codes only'}/><Toggle value={policy.operations.offlineContinuity} onChange={v=>patch(p=>{p.operations.offlineContinuity=v})} label={ar?'استمرارية دون إنترنت':'Offline continuity'}/></div><div className="grid sm:grid-cols-2 gap-4"><NumberControl label={ar?'مهلة التأخر بالدقائق':'Late grace minutes'} value={policy.operations.lateArrivalGraceMinutes} onChange={v=>patch(p=>{p.operations.lateArrivalGraceMinutes=v})}/><Control label={ar?'البطاقة':'Badge'}><TinySelect value={policy.operations.badgeMode} onChange={v=>patch(p=>{p.operations.badgeMode=v as any})}><option value="digital">{ar?'رقمية':'Digital'}</option><option value="print">{ar?'مطبوعة':'Print'}</option><option value="both">{ar?'الاثنان':'Both'}</option><option value="none">{ar?'بدون':'None'}</option></TinySelect></Control></div></div>;

const QuestionsSection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'FairDraw والأسئلة':'FairDraw & questions'} subtitle={ar?'العشوائية ليست هي العدالة؛ هذه المسابقة تحدد القيود والتنوع والصعوبة.':'Randomness alone is not fairness; this competition defines constraints, diversity and difficulty.'}/><div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4"><Control label={ar?'طريقة السحب':'Draw mode'}><TinySelect value={policy.questions.drawMode} onChange={v=>patch(p=>{p.questions.drawMode=v as any})}><option value="fairdraw">FairDraw</option><option value="pure_random">{ar?'عشوائي':'Pure random'}</option><option value="manual_approved">{ar?'معتمد يدوي':'Approved manual'}</option><option value="hybrid">{ar?'هجين':'Hybrid'}</option></TinySelect></Control><NumberControl label={ar?'عدد الأسئلة':'Questions'} value={policy.questions.questionsPerParticipant} onChange={v=>patch(p=>{p.questions.questionsPerParticipant=Math.max(1,v)})}/><NumberControl label={ar?'الصعوبة المستهدفة':'Target difficulty'} step={0.1} value={policy.questions.targetDifficulty} onChange={v=>patch(p=>{p.questions.targetDifficulty=v})}/><NumberControl label={ar?'هامش الصعوبة':'Difficulty tolerance'} step={0.05} value={policy.questions.difficultyTolerance} onChange={v=>patch(p=>{p.questions.difficultyTolerance=Math.max(0,v)})}/><Control label={ar?'طريقة البداية':'Prompt mode'}><TinySelect value={policy.questions.promptMode} onChange={v=>patch(p=>{p.questions.promptMode=v as any})}><option value="configurable">{ar?'حسب الإعداد':'Configurable'}</option><option value="judge">{ar?'المحكم':'Judge'}</option><option value="certified_audio">{ar?'صوت بشري معتمد':'Certified human audio'}</option><option value="visual">{ar?'مرئي':'Visual'}</option></TinySelect></Control></div><div className="mizan-surface-soft px-4"><Toggle value={policy.questions.participantInitiatedDraw} onChange={v=>patch(p=>{p.questions.participantInitiatedDraw=v})} label={ar?'المتسابق يبدأ السحب':'Participant initiates draw'}/><Toggle value={policy.questions.avoidRepeatWithinRound} onChange={v=>patch(p=>{p.questions.avoidRepeatWithinRound=v})} label={ar?'تجنب التكرار داخل الجولة':'Avoid repeats within round'}/><Toggle value={policy.questions.diversity.acrossJuz} onChange={v=>patch(p=>{p.questions.diversity.acrossJuz=v})} label={ar?'تنوع بين الأجزاء':'Across-Juz diversity'}/><Toggle value={policy.questions.diversity.acrossSurah} onChange={v=>patch(p=>{p.questions.diversity.acrossSurah=v})} label={ar?'تنوع بين السور':'Across-Surah diversity'}/><Toggle value={policy.questions.diversity.mutashabihatBalance} onChange={v=>patch(p=>{p.questions.diversity.mutashabihatBalance=v})} label={ar?'موازنة المتشابهات':'Mutashabihat balance'}/></div></div>;

const JudgingSection=({store,ar,policy,patch}:{store:Store;ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=>{const r=store.competition.ruleSet;return <div className="space-y-5"><SectionTitle title={ar?'سياسة التحكيم':'Judging policy'} subtitle={ar?'المحكم يسجل الحدث العلمي، والنظام يحسب وفق لائحة هذه المسابقة فقط.':'Judges record scientific events; scoring follows this competition rule set only.'}/><div className="grid sm:grid-cols-2 gap-4"><Control label={ar?'توزيع المهام':'Judge responsibilities'}><TinySelect value={policy.judging.mode} onChange={v=>patch(p=>{p.judging.mode=v as any})}><option value="all_judges_all_criteria">{ar?'الجميع لكل المعايير':'All judges / all criteria'}</option><option value="specialized_judges">{ar?'تخصص':'Specialized'}</option><option value="hybrid">{ar?'هجين':'Hybrid'}</option></TinySelect></Control><Control label={ar?'الهوية':'Identity'}><TinySelect value={policy.judging.identityVisibility} onChange={v=>patch(p=>{p.judging.identityVisibility=v as any})}><option value="code_only">{ar?'الكود فقط':'Code only'}</option><option value="full">{ar?'كاملة':'Full'}</option><option value="custom">{ar?'مخصصة':'Custom'}</option></TinySelect></Control><Control label={ar?'إدخال الدرجة':'Score input'}><TinySelect value={policy.judging.scoreEntryMode} onChange={v=>patch(p=>{p.judging.scoreEntryMode=v as any})}><option value="event_based">{ar?'بالأحداث':'Event based'}</option><option value="direct_score">{ar?'درجة مباشرة':'Direct score'}</option><option value="hybrid">{ar?'هجين':'Hybrid'}</option></TinySelect></Control><NumberControl label={ar?'عدد المحكمين':'Judges per panel'} value={r.judgesCountPerPanel} onChange={v=>store.updateRuleSet({judgesCountPerPanel:Math.max(1,v)})}/></div><div className="mizan-surface-soft px-4"><Toggle value={policy.judging.independentUntilLock} onChange={v=>patch(p=>{p.judging.independentUntilLock=v})} label={ar?'مستقل حتى القفل':'Independent until lock'}/><Toggle value={policy.judging.requireAudioRecording} onChange={v=>patch(p=>{p.judging.requireAudioRecording=v})} label={ar?'تسجيل الصوت مطلوب':'Audio recording required'}/><Toggle value={policy.judging.allowPhysicalJudgePad} onChange={v=>patch(p=>{p.judging.allowPhysicalJudgePad=v})} label={ar?'Judge Pad / اختصارات':'Judge Pad / shortcuts'}/><Toggle value={policy.judging.silentAiGuardian} onChange={v=>patch(p=>{p.judging.silentAiGuardian=v})} label={ar?'AI صامت للمراجعة فقط':'Silent AI review only'}/><Toggle value={policy.judging.calibrationRequired} onChange={v=>patch(p=>{p.judging.calibrationRequired=v})} label={ar?'معايرة المحكمين':'Judge calibration'}/><Toggle value={policy.judging.reserveJudgeAllowed} onChange={v=>patch(p=>{p.judging.reserveJudgeAllowed=v})} label={ar?'محكم احتياط':'Reserve judge'}/><Toggle value={r.dropExtremes} onChange={v=>store.updateRuleSet({dropExtremes:v})} label={ar?'إسقاط أعلى وأدنى درجة':'Drop highest and lowest'}/></div>
 <div><div className="text-xs font-black text-[#6d746f] mb-2">{ar?'معايير الدرجة':'Score criteria'}</div><div className="divide-y divide-[#e5e3dc] border-y border-[#e5e3dc]">{r.criteria.map((c,i)=><div key={c.id} className="py-3 grid grid-cols-[1fr_90px] gap-3 items-center"><div><div className="text-sm font-bold">{ar?c.nameArabic:c.name}</div><div className="text-[11px] text-[#7c837e]">{c.id}</div></div><input type="number" value={c.maxScore} onChange={e=>{const criteria=[...r.criteria];criteria[i]={...criteria[i],maxScore:Number(e.target.value)};store.updateRuleSet({criteria})}} className="rounded-lg border border-[#ddd] px-2 py-1.5 text-sm"/></div>)}</div></div>
 <div><div className="flex items-center justify-between mb-2"><div className="text-xs font-black text-[#6d746f]">{ar?'أزرار المحكم':'Judge actions'}</div><button onClick={()=>patch(p=>p.judging.actions.push({id:`custom-${Date.now()}`,eventType:`custom_${Date.now()}`,labelArabic:'إجراء',labelEnglish:'Action',shortArabic:'إجراء',shortEnglish:'Action',criterion:'custom',penalty:0,enabled:true,icon:'custom'}))} className="flex items-center gap-1 text-xs font-bold text-[#214C40]"><Plus className="w-3.5 h-3.5"/>{ar?'إجراء':'Action'}</button></div><div className="divide-y divide-[#e5e3dc] border-y border-[#e5e3dc]">{policy.judging.actions.map((a,i)=><div key={a.id} className="py-3 grid sm:grid-cols-[1fr_110px_80px_auto] gap-2 items-center"><input value={ar?a.labelArabic:a.labelEnglish} onChange={e=>patch(p=>{if(ar)p.judging.actions[i].labelArabic=e.target.value;else p.judging.actions[i].labelEnglish=e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-sm font-bold"/><select value={a.criterion} onChange={e=>patch(p=>{p.judging.actions[i].criterion=e.target.value as any})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs"><option value="memorization">Hifz</option><option value="tajweed">Tajweed</option><option value="waqf_ibtida">Waqf</option><option value="performance">Performance</option><option value="custom">Custom</option></select><input type="number" step="0.25" value={a.penalty} onChange={e=>patch(p=>{p.judging.actions[i].penalty=Number(e.target.value)})} className="rounded-lg border border-[#ddd] px-2 py-2 text-xs"/><Chip active={a.enabled} onClick={()=>patch(p=>{p.judging.actions[i].enabled=!p.judging.actions[i].enabled})}>{a.enabled?(ar?'مفعّل':'On'):(ar?'Off':'Off')}</Chip></div>)}</div></div><div className="grid sm:grid-cols-2 gap-4"><NumberControl label={ar?'الحد الأدنى للنجاح':'Minimum pass'} value={r.minimumPassingScore} onChange={v=>store.updateRuleSet({minimumPassingScore:v})}/><NumberControl label={ar?'مدة السؤال بالدقائق':'Question minutes'} value={r.questionDurationMinutes} onChange={v=>store.updateRuleSet({questionDurationMinutes:Math.max(1,v)})}/></div><div className="rounded-xl bg-[#E7EEE9] text-[#214C40] p-3 text-xs font-semibold">{ar?'AI لا يخصم درجة إطلاقًا. أي إشارة آلية تتحول إلى طلب مراجعة بشرية بعد قفل المحكمين.':'AI never deducts a score. Any machine observation becomes a human review suggestion only after judges lock.'}</div></div>};

const AppealsSection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'سياسة الاعتراض':'Appeals policy'} subtitle={ar?'كل مسابقة تقرر هل يوجد اعتراض، مدته، أسبابه، ومن يراجعه.':'Each competition decides whether appeals exist, their window, grounds and reviewer.'}/><div className="mizan-surface-soft px-4"><Toggle value={policy.appeals.enabled} onChange={v=>patch(p=>{p.appeals.enabled=v})} label={ar?'الاعتراضات مفعلة':'Appeals enabled'}/><Toggle value={policy.appeals.allowScoreChange} onChange={v=>patch(p=>{p.appeals.allowScoreChange=v})} label={ar?'يمكن أن ينتج تعديل درجة بعد قرار بشري':'Human appeal decision may change score'}/></div>{policy.appeals.enabled&&<div className="grid sm:grid-cols-2 gap-4"><NumberControl label={ar?'النافذة بالساعات':'Window hours'} value={policy.appeals.windowHours} onChange={v=>patch(p=>{p.appeals.windowHours=Math.max(1,v)})}/><Control label={ar?'المراجع':'Reviewer'}><TinySelect value={policy.appeals.reviewerRole} onChange={v=>patch(p=>{p.appeals.reviewerRole=v as any})}><option value="head_judge">Head Judge</option><option value="scientific_admin">Scientific Admin</option><option value="committee">Committee</option></TinySelect></Control></div>}<div><div className="text-xs font-black text-[#6d746f] mb-2">{ar?'الأسباب المسموحة':'Allowed grounds'}</div><div className="flex flex-wrap gap-2">{policy.appeals.grounds.map(g=><Badge key={g} variant="neutral" dot={false}>{g}</Badge>)}</div></div></div>;

const ResultPolicySection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'النتائج والاعتماد':'Results & sealing'} subtitle={ar?'النتيجة قد تكون فورية أو خاصة أو مؤجلة للحفل حسب سياسة المسابقة.':'Visibility can be immediate, private, delayed or ceremony-only.'}/><div className="grid sm:grid-cols-2 gap-4"><Control label={ar?'الإظهار':'Visibility'}><TinySelect value={policy.results.visibility} onChange={v=>patch(p=>{p.results.visibility=v as any})}><option value="immediate">{ar?'فوري':'Immediate'}</option><option value="after_committee">{ar?'بعد اللجنة':'After committee'}</option><option value="after_round">{ar?'بعد الجولة':'After round'}</option><option value="ceremony_only">{ar?'الحفل فقط':'Ceremony only'}</option><option value="private_only">{ar?'خاص':'Private only'}</option></TinySelect></Control><Control label={ar?'الترتيب العام':'Leaderboard'}><TinySelect value={policy.results.publicLeaderboard} onChange={v=>patch(p=>{p.results.publicLeaderboard=v as any})}><option value="disabled">{ar?'متوقف':'Disabled'}</option><option value="top_only">{ar?'الأوائل فقط':'Top only'}</option><option value="full">{ar?'كامل':'Full'}</option></TinySelect></Control><Control label={ar?'التأهل':'Qualification'}><TinySelect value={policy.results.qualificationRule} onChange={v=>patch(p=>{p.results.qualificationRule=v as any})}><option value="top_n">Top N</option><option value="minimum_score">{ar?'حد أدنى':'Minimum score'}</option><option value="custom">{ar?'مخصص':'Custom'}</option></TinySelect></Control><NumberControl label={ar?'قيمة التأهل':'Qualification value'} value={policy.results.qualificationValue} onChange={v=>patch(p=>{p.results.qualificationValue=v})}/></div><div className="mizan-surface-soft px-4"><Toggle value={policy.results.requireDualApprovalToSeal} onChange={v=>patch(p=>{p.results.requireDualApprovalToSeal=v})} label={ar?'اعتمادان مستقلان قبل الختم':'Two independent approvals before seal'}/></div><div><div className="text-xs font-black text-[#6d746f] mb-2">{ar?'قواعد كسر التعادل':'Tie-break order'}</div><div className="flex flex-wrap gap-2">{policy.results.tieBreakRules.map((x,i)=><Badge key={`${x}-${i}`} variant="neutral" dot={false}>{i+1}. {x}</Badge>)}</div></div></div>;

const CertificateSection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=>{const cp=policy.certificates;return <div className="space-y-5"><SectionTitle title={ar?'سياسة الشهادات':'Certificate policy'} subtitle={ar?'الشهادة جزء من سياسة المسابقة وليست قالبًا ثابتًا من MIZAN.':'Certificates follow the competition policy, not a global MIZAN template.'}/><div className="mizan-surface-soft px-4"><Toggle value={cp.enabled} onChange={v=>patch(p=>{p.certificates.enabled=v})} label={ar?'الشهادات مفعلة':'Certificates enabled'}/><Toggle value={cp.autoIssue} onChange={v=>patch(p=>{p.certificates.autoIssue=v})} label={ar?'إصدار تلقائي بعد الإغلاق':'Auto issue after finalization'}/><Toggle value={cp.publicVerification} onChange={v=>patch(p=>{p.certificates.publicVerification=v})} label={ar?'تحقق عام':'Public verification'}/><Toggle value={cp.showScore} onChange={v=>patch(p=>{p.certificates.showScore=v})} label={ar?'إظهار الدرجة':'Show score'}/><Toggle value={cp.showRank} onChange={v=>patch(p=>{p.certificates.showRank=v})} label={ar?'إظهار الترتيب':'Show rank'}/></div><div className="grid sm:grid-cols-2 gap-4"><Control label={ar?'من يستلم':'Issue for'}><TinySelect value={cp.issueFor} onChange={v=>patch(p=>{p.certificates.issueFor=v as any})}><option value="all_participants">{ar?'كل المشاركين':'All participants'}</option><option value="qualified">{ar?'المتأهلون':'Qualified'}</option><option value="winners">{ar?'الفائزون':'Winners'}</option><option value="custom">{ar?'مخصص — يحتاج قاعدة':'Custom rule required'}</option></TinySelect></Control><TextControl label={ar?'عنوان الشهادة':'Certificate title'} value={ar?(cp.titleArabic||''):(cp.titleEnglish||'')} onChange={v=>patch(p=>{if(ar)p.certificates.titleArabic=v;else p.certificates.titleEnglish=v})}/></div><Control label={ar?'النص المختصر':'Award text'}><textarea value={ar?(cp.awardTextArabic||''):(cp.awardTextEnglish||'')} onChange={e=>patch(p=>{if(ar)p.certificates.awardTextArabic=e.target.value;else p.certificates.awardTextEnglish=e.target.value})} className="w-full min-h-24 rounded-xl border border-[#dcdad2] bg-white px-3 py-3 text-sm resize-none"/></Control><div><div className="flex items-center justify-between"><div className="text-xs font-black text-[#6d746f]">{ar?'الموقعون':'Signatories'}</div><button onClick={()=>patch(p=>{p.certificates.signatories=[...(p.certificates.signatories||[]),{name:ar?'اسم الموقّع':'Signatory',title:ar?'الصفة':'Title'}]})} className="flex items-center gap-1 text-xs font-bold text-[#214C40]"><Plus className="w-3.5 h-3.5"/>{ar?'موقّع':'Signatory'}</button></div><div className="divide-y divide-[#e5e3dc] mt-2">{(cp.signatories||[]).map((s,i)=><div key={i} className="py-3 grid grid-cols-[1fr_1fr_auto] gap-2"><input value={s.name} onChange={e=>patch(p=>{p.certificates.signatories![i].name=e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-sm"/><input value={s.title} onChange={e=>patch(p=>{p.certificates.signatories![i].title=e.target.value})} className="rounded-lg border border-[#ddd] px-2 py-2 text-sm"/><button onClick={()=>patch(p=>{p.certificates.signatories=p.certificates.signatories?.filter((_,x)=>x!==i)})} aria-label="remove signatory" className="w-9 h-9 rounded-lg hover:bg-[#f2e8e5] text-[#9a5d54] grid place-items-center"><Trash2 className="w-4 h-4"/></button></div>)}</div></div></div>};

const PrivacySection=({ar,policy,patch}:{ar:boolean;policy:CompetitionPolicy;patch:(fn:(p:CompetitionPolicy)=>void)=>void})=><div className="space-y-5"><SectionTitle title={ar?'الخصوصية والاحتفاظ':'Privacy & retention'} subtitle={ar?'لا توجد سياسة احتفاظ واحدة لكل الجهات؛ هذه القيم تخص المسابقة الحالية.':'Retention is competition-specific and should match the organization’s legal policy.'}/><div className="grid sm:grid-cols-2 gap-4"><NumberControl label={ar?'الصوت — أيام':'Audio days'} value={policy.privacy.audioRetentionDays} onChange={v=>patch(p=>{p.privacy.audioRetentionDays=Math.max(0,v)})}/><NumberControl label={ar?'المستندات — أيام':'Document days'} value={policy.privacy.documentRetentionDays} onChange={v=>patch(p=>{p.privacy.documentRetentionDays=Math.max(0,v)})}/></div><div className="mizan-surface-soft px-4"><Toggle value={policy.privacy.allowAiProcessing} onChange={v=>patch(p=>{p.privacy.allowAiProcessing=v})} label={ar?'السماح بـAI المساند':'Allow assistive AI processing'}/><Toggle value={policy.privacy.displayParticipantNameOnPublicScreens} onChange={v=>patch(p=>{p.privacy.displayParticipantNameOnPublicScreens=v})} label={ar?'إظهار الاسم على الشاشات العامة':'Show participant names publicly'}/><Toggle value={policy.privacy.allowAnonymousBenchmarking} onChange={v=>patch(p=>{p.privacy.allowAnonymousBenchmarking=v})} label={ar?'مقارنات مجهولة الهوية':'Anonymous benchmarking'}/></div></div>;

const ParticipantsView=({store,ar,query,setQuery,filtered}:{store:Store;ar:boolean;query:string;setQuery:(s:string)=>void;filtered:Store['participants']})=><div className="space-y-4"><div className="flex items-end justify-between gap-4"><div><div className="mizan-kicker">PARTICIPANTS</div><h1 className="text-3xl font-black mt-1">{store.participants.length}</h1></div><div className="relative w-full max-w-xs"><Search className="absolute start-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#868c88]"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={ar?'اسم أو كود':'Name or code'} className="w-full rounded-xl border border-[#dcdad2] bg-white ps-10 pe-3 py-2.5 text-sm"/></div></div><div className="mizan-surface overflow-hidden"><div className="divide-y divide-[#e5e3dc]">{filtered.map(p=>{const cat=store.competition.categories.find(c=>c.id===p.categoryId);const needs=p.status==='submitted'||p.status==='under_review';return <div key={p.id} className="p-4 sm:px-5 flex items-center gap-4"><div className="w-11 h-11 rounded-xl bg-[#E7EEE9] text-[#214C40] grid place-items-center font-black text-xs">{p.code.replace('A-','')}</div><div className="min-w-0 flex-1"><div className="font-bold text-sm truncate">{ar?p.fullNameArabic:p.fullName}</div><div className="text-[11px] text-[#7b827d] mt-1 truncate">{ar?cat?.nameArabic:cat?.name} · {p.country||'—'}</div></div><Badge variant={p.status==='in_queue'?'amber':p.status==='tested'||p.status==='certified'?'emerald':'neutral'}>{statusLabel(p.status,ar)}</Badge>{needs&&<div className="flex gap-1"><Button size="sm" variant="secondary" onClick={()=>store.reviewParticipant(p.id,'approved')}>{ar?'اعتماد':'Approve'}</Button><Button size="sm" variant="ghost" onClick={()=>store.reviewParticipant(p.id,'rejected')}>{ar?'رفض':'Reject'}</Button></div>}</div>})}</div></div></div>;

const OperationsView=({store,ar,sim,simCount,setSimCount,attention}:{store:Store;ar:boolean;sim:any;simCount:number;setSimCount:(n:number)=>void;attention:any[]})=><div className="space-y-4"><div className="flex items-end justify-between"><div><div className="mizan-kicker">MIZAN AUTOPILOT</div><h1 className="text-3xl font-black mt-1">{ar?'شغّل بالاستثناء':'Operate by exception'}</h1></div><Button size="sm" variant="outline" onClick={()=>store.addCommittee()} icon={<Plus className="w-4 h-4"/>}>{ar?'لجنة':'Panel'}</Button></div><div className="grid sm:grid-cols-2 xl:grid-cols-4 gap-3">{store.committees.map(c=><div key={c.id} className="mizan-surface p-4"><div className="flex justify-between"><Badge variant={c.status==='offline'?'rose':c.status==='testing'?'blue':'emerald'}>{c.code}</Badge><select value={c.status} onChange={e=>store.updateCommittee(c.id,{status:e.target.value as any})} className="text-[11px] bg-transparent outline-none text-[#737a75]"><option value="ready">ready</option><option value="testing">testing</option><option value="paused">paused</option><option value="offline">offline</option></select></div><input value={ar?c.nameArabic:c.name} onChange={e=>store.updateCommittee(c.id,ar?{nameArabic:e.target.value}:{name:e.target.value})} className="w-full bg-transparent border-0 p-0 font-bold text-sm mt-4 outline-none"/><div className="mt-3 flex items-center justify-between"><span className="text-xs text-[#7b827d]">{c.completedCount} {ar?'مكتمل':'done'}</span><label className="text-[10px] text-[#7b827d] flex items-center gap-1"><Clock3 className="w-3 h-3"/><input type="number" step="0.1" value={c.averageSessionMinutes} onChange={e=>store.updateCommittee(c.id,{averageSessionMinutes:Number(e.target.value)})} className="w-12 bg-transparent border-b border-[#ddd] text-end"/></label></div></div>)}</div><div className="grid xl:grid-cols-[1fr_.55fr] gap-4"><div className="mizan-surface p-5"><div className="flex items-center justify-between mb-5"><div><div className="mizan-kicker">DIGITAL TWIN</div><h2 className="font-extrabold mt-1">{ar?'اختبر السعة قبل اليوم الحقيقي':'Test capacity before event day'}</h2></div><div className="flex items-center gap-2"><Button size="sm" variant="outline" onClick={()=>store.optimizeArrivalSlots()}>{ar?'تحسين الوصول':'Optimize arrivals'}</Button><input type="number" min={1} max={40} value={simCount} onChange={e=>setSimCount(Number(e.target.value))} className="w-16 rounded-xl border border-[#ddd] px-2 py-2 text-center text-sm font-bold"/></div></div><div className="grid grid-cols-3 gap-3"><MiniMetric value={sim.projectedFinishTime} label={ar?'انتهاء':'Finish'}/><MiniMetric value={`${sim.averageWaitMinutes}m`} label={ar?'انتظار':'Wait'}/><MiniMetric value={`${sim.maxWaitMinutes}m`} label={ar?'أقصى':'Max'}/></div><div className="mt-4 rounded-xl bg-[#E7EEE9] p-3 text-xs font-semibold text-[#214C40]">{ar?sim.optimizationAdviceArabic:sim.optimizationAdviceEnglish}</div></div><div className="mizan-surface p-5"><div className="mizan-kicker">EXCEPTIONS</div><div className="mt-4 space-y-2">{attention.filter(x=>x.kind!=='setup').length?attention.filter(x=>x.kind!=='setup').map(x=><div key={x.id} className="flex items-start gap-2 text-xs font-semibold"><CircleAlert className="w-4 h-4 text-[#9B7542] shrink-0"/>{x.title}</div>):<div className="text-center py-8 text-xs text-[#7b827d]"><BadgeCheck className="w-6 h-6 text-[#2F6555] mx-auto mb-2"/>{ar?'لا توجد حالات':'No active exceptions'}</div>}</div></div></div></div>;

const ResultsView=({store,ar}:{store:Store;ar:boolean})=>{const policy=getCompetitionPolicy(store.competition); const pending=store.appeals.filter(a=>a.status==='submitted'||a.status==='under_review').length; const allSealed=store.results.length>0&&store.results.every(r=>r.status==='sealed'||r.status==='published');return <div className="space-y-4"><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="mizan-kicker">RESULTS</div><h1 className="text-3xl font-black mt-1">{ar?'اعتماد، ختم، نشر':'Approve · seal · publish'}</h1><p className="text-sm text-[#757c77] mt-2">{ar?`الإظهار: ${policy.results.visibility}`:`Visibility: ${policy.results.visibility}`}</p></div><div className="flex gap-2"><Button variant="outline" onClick={()=>store.sealResults()} icon={<LockKeyhole className="w-4 h-4"/>}>{policy.results.requireDualApprovalToSeal?(ar?`اعتماد الختم (${new Set(store.sealApprovals.map(a=>a.actorId)).size}/2)`:`Seal approval (${new Set(store.sealApprovals.map(a=>a.actorId)).size}/2)`):(ar?'ختم':'Seal')}</Button><Button disabled={!allSealed} onClick={()=>store.publishResults()}>{ar?'نشر':'Publish'}</Button></div></div>{pending>0&&<div className="rounded-xl bg-[#F2EADC] text-[#725630] p-3 text-xs font-bold">{ar?`${pending} اعتراضات تحتاج حسمًا قبل الإغلاق`:`${pending} appeals require resolution before closure`}</div>}<div className="mizan-surface overflow-hidden"><div className="divide-y divide-[#e5e3dc]">{[...store.results].sort((a,b)=>a.rank-b.rank).map(r=><div key={r.id} className="p-4 sm:px-5 flex items-center gap-4"><div className="w-10 text-2xl font-black text-[#214C40]">{r.rank||'—'}</div><div className="min-w-0 flex-1"><div className="font-bold text-sm truncate">{ar?r.participantNameArabic:r.participantName}</div><div className="text-[11px] text-[#7b827d] mt-1">{r.categoryName} · {r.country}</div></div><div className="font-black tabular-nums">{r.finalScore.toFixed(2)}</div><Badge variant={r.status==='sealed'||r.status==='published'?'emerald':'neutral'}>{r.status}</Badge><button disabled={!['sealed','published'].includes(r.status)} onClick={()=>store.generateCertificate(r.id)} title={ar?'إصدار شهادة':'Issue certificate'} className="w-9 h-9 rounded-xl grid place-items-center hover:bg-[#efede7] text-[#59615c] disabled:opacity-30"><Award className="w-4 h-4"/></button></div>)}</div></div><div className="text-xs text-[#7b827d]">{store.certificates.length} {ar?'شهادة':'certificates'} · {store.auditLogs.length} {ar?'حدث تدقيق':'audit events'}</div></div>};

const RegistrationFieldRow=({f,ar,onVisible,onRequired}:{f:RegistrationFieldDefinition;ar:boolean;onVisible:(v:boolean)=>void;onRequired:(v:boolean)=>void})=><div className="py-3 grid grid-cols-[1fr_auto] items-center gap-3"><div><div className="text-sm font-bold">{ar?f.labelArabic:f.labelEnglish}</div><div className="text-[11px] text-[#7c837e]">{f.type}</div></div><div className="flex gap-1"><Chip active={f.visible} onClick={()=>onVisible(!f.visible)}>{f.visible?(ar?'ظاهر':'Visible'):(ar?'مخفي':'Hidden')}</Chip><Chip active={f.required} amber onClick={()=>onRequired(!f.required)}>{f.required?(ar?'إلزامي':'Required'):(ar?'اختياري':'Optional')}</Chip></div></div>;
const Toggle=({value,onChange,label}:{value:boolean;onChange:(v:boolean)=>void;label:string})=><button type="button" onClick={()=>onChange(!value)} className="w-full flex items-center justify-between gap-4 py-3 text-start border-b border-[#e7e5de] last:border-0"><span className="text-sm font-semibold text-[#303733]">{label}</span><span className={`relative w-10 h-6 rounded-full transition ${value?'bg-[#214C40]':'bg-[#d6d4cd]'}`}><span className={`absolute top-1 w-4 h-4 rounded-full bg-white shadow-sm transition ${value?'end-1':'end-5'}`}/></span></button>;
const Chip=({active=false,amber=false,onClick,children}:{active?:boolean;amber?:boolean;onClick:()=>void;children:React.ReactNode})=><button type="button" onClick={onClick} className={`px-2.5 py-1.5 rounded-lg text-[11px] font-bold ${active?(amber?'bg-[#F2EADC] text-[#7d5e34]':'bg-[#E7EEE9] text-[#214C40]'):'bg-[#efede7] text-[#777]'}`}>{children}</button>;
const NavButton=({active,onClick,icon:Icon,label}:{active:boolean;onClick:()=>void;icon:React.ComponentType<{className?:string}>;label:string})=><button onClick={onClick} className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm font-bold transition ${active?'bg-[#214C40] text-white':'text-[#626a65] hover:bg-[#efede7] hover:text-[#303733]'}`}><Icon className="w-4 h-4"/><span>{label}</span></button>;
const TinySelect=({value,onChange,children}:{value:string;onChange:(v:string)=>void;children:React.ReactNode})=><select value={value} onChange={e=>onChange(e.target.value)} className="w-full rounded-xl border border-[#dcdad2] bg-white px-3 py-2.5 text-sm font-semibold text-[#303733]">{children}</select>;
const SectionTitle=({title,subtitle}:{title:string;subtitle:string})=><div><h2 className="text-xl font-black text-[#202622]">{title}</h2><p className="text-xs text-[#777e79] mt-1.5 max-w-2xl">{subtitle}</p></div>;
const Control=({label,children}:{label:string;children:React.ReactNode})=><label className="block"><span className="block text-xs font-black text-[#686f6a] mb-2">{label}</span>{children}</label>;
const TextControl=({label,value,onChange,type='text'}:{label:string;value:string;onChange:(v:string)=>void;type?:string})=><Control label={label}><input type={type} value={value} onChange={e=>onChange(e.target.value)} className="w-full rounded-xl border border-[#dcdad2] bg-white px-3 py-2.5 text-sm font-semibold"/></Control>;
const NumberControl=({label,value,onChange,step=1}:{label:string;value:number;onChange:(v:number)=>void;step?:number})=><Control label={label}><input type="number" step={step} value={value} onChange={e=>onChange(Number(e.target.value))} className="w-full rounded-xl border border-[#dcdad2] bg-white px-3 py-2.5 text-sm font-semibold"/></Control>;
const MetricCard=({icon:Icon,value,label}:{icon:React.ComponentType<{className?:string}>;value:number|string;label:string})=><div className="mizan-surface p-4 sm:p-5"><Icon className="w-4 h-4 text-[#2F6555] mb-4"/><div className="text-2xl sm:text-3xl font-black">{value}</div><div className="text-xs text-[#747b76] mt-1">{label}</div></div>;
const MiniMetric=({value,label}:{value:string;label:string})=><div className="rounded-xl bg-[#f1efe9] p-4"><div className="text-xl font-black">{value}</div><div className="text-[11px] text-[#757c77] mt-1">{label}</div></div>;
const workflowLabel=(id:string,ar:boolean)=>({register:ar?'التسجيل':'Register',verify:ar?'التحقق':'Verify',approve:ar?'الاعتماد':'Approve',schedule:ar?'الجدولة':'Schedule',notify:ar?'الإشعار':'Notify',checkin:ar?'الحضور':'Check-in',route:ar?'التوجيه':'Route',draw:ar?'السحب':'Draw',judge:ar?'التحكيم':'Judge',integrity:ar?'النزاهة':'Integrity',seal:ar?'الختم':'Seal',publish:ar?'النشر':'Publish',certificate:ar?'الشهادة':'Certificate'} as Record<string,string>)[id]||id;
const statusLabel=(s:string,ar:boolean)=>({submitted:ar?'مرسل':'Submitted',under_review:ar?'مراجعة':'Review',approved:ar?'مقبول':'Approved',checked_in:ar?'حضر':'Checked in',in_queue:ar?'ينتظر':'Waiting',in_session:ar?'داخل اللجنة':'In session',tested:ar?'اختبر':'Tested',appealed:ar?'اعتراض':'Appeal',certified:ar?'معتمد':'Certified',draft:ar?'مسودة':'Draft',rejected:ar?'مرفوض':'Rejected'} as Record<string,string>)[s]||s;
